        ART.put("cos_suffix", new Art(new String[]{"................","................","..OOOOOOOOOOOO..",".OPPPPPPPPPPPPO.",".OPwwwwwPPPPYPO.",".OPPPPPPPPPYYYO.",".OPwwwwPPPPPYPO.",".OPPPPPPPPPPPPO.","..OOOOOOOOOOOO..","................","................","................","................","................","................","................"}, "OPwY", new int[]{0xFF2A3350,0xFF39466E,0xFFC4CBDC,0xFFFFD23C}, 0xFFFFFFFF, 0xFFFFFFFF, 0xFFFFFFFF, 0xFFFFFFFF, 0));
        ART.put("cos_name", new Art(new String[]{"................","................","..OOOOOOOOOOOO..",".OPPPPPPPPPPPPO.",".OPrrPooPyyPggO.",".OPrrPooPyyPggO.",".OPrrPooPyyPggO.",".OPPPPPPPPPPPPO.","..OOOOOOOOOOOO..","................","................","................","................","................","................","................"}, "OProyg", new int[]{0xFF2A3350,0xFF39466E,0xFFFF5A6E,0xFFFFA02E,0xFFFFD23C,0xFF4FD88A}, 0xFFFFFFFF, 0xFFFFFFFF, 0xFFFFFFFF, 0xFFFFFFFF, 0));
